"""Patch gen_perf_core.py for run 6 boot F1: the core rows with the L3 on (bandwidth, multi-core, OCM bandwidth, mesh counters, CPUs 4 and 6)."""
path = "/home/jhan/workspace/titan/cache-perf/asimov/gen_perf_core.py"
s = open(path).read()
def rep(start, end, new):
    global s
    assert s.count(start) == 1, ("start", start[:60], s.count(start)); assert s.count(end) == 1, ("end", end[:60], s.count(end))
    i, j = s.index(start), s.index(end); assert i < j; s = s[:i] + new + s[j:]
def sub(old, new):
    global s
    assert s.count(old) == 1, ("sub", old[:70], s.count(old)); s = s.replace(old, new)

